"""Kickoff 56 analysis, fixed before the data (section 3 of the kickoff; k56-rule.md).

Kickoff 52's fits and conventions: analyse_52.py's functions (a byte-identical copy) fit, theta_R, theta_W, wrap, near and
pct, unchanged. Its analyse() is written for two qubits (143, 144) and Kickoff 52's verdict, so it does not apply as is;
the loop below follows it step for step, in the same bootstrap order, for the three qubits of k56-rule.md and its verdict.

Per M (7, then 43, then 18), from the counts of the 126 positions (63 circuits, 2 copies each):
- F_no(phi) and F_ref: the squared Hellinger overlap with the wait test's phi = 0 parity ideal (manacitra.wait), pooled
  over the two copies; the outcome keys in the repository's order (tests/_reuse_runs.py at e45f15d, _wait_test_keys).
- M's P(1) from its own bit, pooled over the two copies; loss = P(1) - P(1) of Z.
- The fit: y(phi) = c + b cos(phi) + s sin(phi), OLS over the six phases. R0 and R1: y = loss, theta = atan2(s, -b).
  W-no: y = F_no, theta = atan2(-s, b).
- L = theta_W - theta_R1, wrapped to (-180, +180]. Beside: theta_W - theta_R0 and theta_R1 - theta_R0; each fit's
  amplitude and residuals; d1(phi) and d0(phi) at the six phases; the lean (mean d1 over the six phases); the pulse
  cost (P(1) after H, XY4's four pulses, H, minus Z's P(1)).
- 90% intervals (5th and 95th percentiles) from one joint bootstrap, seed 56, 10,000 draws, refitting on every
  resample, in a fixed order: M by M; F for W-no at 0, 60, ..., 300, then W-ref (copies with replacement, each redrawn
  from a multinomial); then P(1) for Z, R0 at the six phases, R1 at the six phases (copies with replacement, each
  redrawn binomially); after the three M, the pulse-cost circuit's P(1) for 7, 43 and 18, from the same generator.
  Each resample's angle difference is wrapped to within 180 degrees of its point estimate.

H56a on 7, H56b on 43, H56c on 18: LARGE if L's interval lies entirely outside [-10, +10] degrees; SMALL if entirely
inside [-5, +5]; NOT SETTLED otherwise.

Usage: python analyse_56.py                 (Kickoff 56's files)
       python analyse_56.py --synthetic     (stated L of 0 and 25 degrees at theta 0 and -100 degrees)"""
from __future__ import annotations

import hashlib
import json
import math
import sys
import time
from collections import defaultdict
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE / "site"))
sys.path.insert(0, str(HERE / "src-e45f15d" / "tests"))
sys.path.insert(0, str(HERE))
import analyse_52 as A52  # noqa: E402  Kickoff 52's fit functions, unchanged

W = A52.W
reuse = A52.reuse
ORDER_M = ("7", "43", "18")
VERDICT_NAME = {"7": "H56a", "43": "H56b", "18": "H56c"}
PHIS = A52.PHIS
SEED, N_BOOT = 56, 10_000
LARGE_DEG, SMALL_DEG = 10.0, 5.0
fit, theta_R, theta_W, wrap, near, pct = A52.fit, A52.theta_R, A52.theta_W, A52.wrap, A52.near, A52.pct
_X = A52._X


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def verdict_of(ci):
    lo, hi = ci
    if lo > LARGE_DEG or hi < -LARGE_DEG:
        return "LARGE"
    if lo > -SMALL_DEG and hi < SMALL_DEG:
        return "SMALL"
    return "NOT SETTLED"


def analyse(labels, counts, order=ORDER_M):
    keys, q = reuse._wait_test_keys()

    def F(V):
        return np.sqrt(V / V.sum(-1, keepdims=True) * q).sum(-1) ** 2

    cells, bits, pooled = defaultdict(list), defaultdict(list), defaultdict(lambda: defaultdict(int))
    for lab, cts in zip(labels, counts):
        key = (str(lab["M"]), lab["circuit"], lab["phi_deg"])
        if lab["part"] == "W":
            d = defaultdict(int)
            for k, n in cts.items():
                kk = k.replace(" ", "")[-W.WAIT_TEST_CLBITS:]
                d[kk] += n
                pooled[key][kk] += n
            cells[key].append((lab["copy"], [d.get(k, 0) for k in keys]))
        else:
            i = lab["m_clbit"]
            ones = sum(n for k, n in cts.items() if k.replace(" ", "")[::-1][i] == "1")
            bits[key].append((lab["copy"], ones, sum(cts.values())))
    for dd in (cells, bits):
        for k in dd:
            dd[k].sort(key=lambda x: x[0])

    rng = np.random.default_rng(SEED)

    def draw_F(key):
        V = np.array([x[1] for x in cells[key]], float)
        freq = V / V.sum(1, keepdims=True)
        idx = rng.integers(0, V.shape[0], size=(N_BOOT, V.shape[0]))
        return F(rng.multinomial(int(V[0].sum()), freq[idx]).sum(1))

    def draw_P(key):
        o = np.array([x[1] for x in bits[key]])
        t = np.array([x[2] for x in bits[key]])
        acc1, accn = np.zeros(N_BOOT), np.zeros(N_BOOT)
        for _ in range(len(o)):
            pick = rng.integers(0, len(o), size=N_BOOT)
            acc1 += rng.binomial(t[pick], o[pick] / t[pick])
            accn += t[pick]
        return acc1 / accn

    ideal = W.wait_test_ideal()
    out, zdraws = {}, {}
    for M in order:
        wkeys = [(M, "W-no", p) for p in PHIS] + [(M, "W-ref", 0)]
        rkeys = [(M, "Z", 0)] + [(M, c, p) for c in ("R0", "R1") for p in PHIS]
        Fb = {k: draw_F(k) for k in wkeys}
        Pb = {k: draw_P(k) for k in rkeys}
        Fp = {k: W.fidelity(dict(pooled[k]), ideal) for k in wkeys}
        P = {k: sum(x[1] for x in bits[k]) / sum(x[2] for x in bits[k]) for k in rkeys}
        z = (M, "Z", 0)
        zdraws[M] = (P[z], Pb[z])
        y = {"W": np.array([Fp[(M, "W-no", p)] for p in PHIS])}
        yb = {"W": np.stack([Fb[(M, "W-no", p)] for p in PHIS], -1)}
        for c in ("R0", "R1"):
            y[c] = np.array([P[(M, c, p)] - P[z] for p in PHIS])
            yb[c] = np.stack([Pb[(M, c, p)] - Pb[z] for p in PHIS], -1)
        th = {"W": float(theta_W(y["W"])), "R0": float(theta_R(y["R0"])), "R1": float(theta_R(y["R1"]))}
        thb = {"W": theta_W(yb["W"]), "R0": theta_R(yb["R0"]), "R1": theta_R(yb["R1"])}
        diffs = {}
        for name, (a, b) in (("L_W_minus_R1", ("W", "R1")), ("W_minus_R0", ("W", "R0")), ("R1_minus_R0", ("R1", "R0"))):
            pt = float(wrap(th[a] - th[b]))
            diffs[name] = {"deg": pt, "ci90": pct(near(wrap(thb[a] - thb[b]), pt))}
        fits = {}
        for c in ("W", "R0", "R1"):
            c0, b, s = fit(y[c])
            _, bb, sb = fit(yb[c])
            fits[c] = {"theta_deg": th[c], "theta_ci90": pct(near(thb[c], th[c])), "c": float(c0), "b": float(b), "s": float(s),
                       "amplitude": float(math.hypot(b, s)), "amplitude_ci90": pct(np.hypot(bb, sb)),
                       "residuals": (y[c] - _X @ np.array([c0, b, s])).tolist(), "y": y[c].tolist(),
                       "label": "a fit (OLS of c + b cos phi + s sin phi over the six phases), fixed before the data"}
        f_ref, f_ref_b = Fp[(M, "W-ref", 0)], Fb[(M, "W-ref", 0)]
        resid = {}
        for t, c in (("d0", "R0"), ("d1", "R1")):
            dp = y["W"] - f_ref * (1 - y[c])
            db = yb["W"] - f_ref_b[:, None] * (1 - yb[c])
            resid[t] = {str(p): float(dp[i]) for i, p in enumerate(PHIS)}
            resid[t + "_ci90"] = {str(p): pct(db[:, i]) for i, p in enumerate(PHIS)}
            resid[f"mean_{t}"] = float(dp.mean())
            resid[f"mean_{t}_ci90"] = pct(db.mean(1))
        out[M] = {"verdict_name": VERDICT_NAME.get(M, M), "verdict": verdict_of(diffs["L_W_minus_R1"]["ci90"]), **diffs, "fits": fits,
                  "F_no": {str(p): Fp[(M, "W-no", p)] for p in PHIS}, "F_no_ci90": {str(p): pct(Fb[(M, "W-no", p)]) for p in PHIS},
                  "F_ref": f_ref, "F_ref_ci90": pct(f_ref_b), "P1_Z": P[z], "P1_Z_ci90": pct(Pb[z]),
                  "loss": {f"{c}|{p}": float(y[c][i]) for c in ("R0", "R1") for i, p in enumerate(PHIS)},
                  "loss_ci90": {f"{c}|{p}": pct(yb[c][:, i]) for c in ("R0", "R1") for i, p in enumerate(PHIS)}, **resid,
                  "lean_mean_d1": resid["mean_d1"], "lean_mean_d1_ci90": resid["mean_d1_ci90"]}
    for M in order:
        k = (M, "XY4", 0)
        if k not in bits:
            continue
        pz, pzb = zdraws[M]
        pb = draw_P(k)
        p = sum(x[1] for x in bits[k]) / sum(x[2] for x in bits[k])
        out[M]["pulse_cost"] = {"P1": p, "P1_ci90": pct(pb), "P1_minus_Z": p - pz, "P1_minus_Z_ci90": pct(pb - pzb)}
    return {**{VERDICT_NAME.get(M, M): out[M]["verdict"] for M in order}, "per_M": out}


def synthetic():
    """Counts drawn from stated distributions through the same code: the R1 loss a sin^2((phi + theta)/2) (a 0.9), the
    R0 loss at theta + 20 degrees, the wait test's F_no f cos^2((phi + theta + L)/2) (f 0.9), at theta 0 and -100 degrees
    and L 0 and 25 degrees; 3,000 shots per copy, as in the run."""
    ideal = W.wait_test_ideal()
    ik = sorted(ideal)
    rng = np.random.default_rng(7)

    def w_counts(f, n=3000):
        p = {k: f / 32 for k in ik}
        p["000001"] = 1 - f
        ks = list(p)
        x = rng.multinomial(n, [p[k] for k in ks])
        return {k: int(v) for k, v in zip(ks, x) if v}

    def r_counts(p1, n=3000, bits=6):
        o = int(rng.binomial(n, min(max(p1, 0.0), 1.0)))
        if bits == 1:
            return {"0": n - o, "1": o}
        return {"0" * bits: n - o, "1" + "0" * (bits - 1): o}

    s2 = lambda x: math.sin(math.radians(x) / 2) ** 2
    c2 = lambda x: math.cos(math.radians(x) / 2) ** 2
    ok = True
    for theta in (0, -100):
        for L in (0, 25):
            labels, counts = [], []
            for M in ORDER_M:
                for cp in (1, 2):
                    for p in PHIS:
                        labels.append({"M": int(M), "part": "W", "circuit": "W-no", "phi_deg": p, "copy": cp}); counts.append(w_counts(0.9 * c2(p + theta + L)))
                        labels.append({"M": int(M), "part": "R", "circuit": "R1", "phi_deg": p, "copy": cp, "m_clbit": 5}); counts.append(r_counts(0.01 + 0.9 * s2(p + theta)))
                        labels.append({"M": int(M), "part": "R", "circuit": "R0", "phi_deg": p, "copy": cp, "m_clbit": 0}); counts.append(r_counts(0.01 + 0.9 * s2(p + theta + 20), bits=1))
                    labels.append({"M": int(M), "part": "W", "circuit": "W-ref", "phi_deg": 0, "copy": cp}); counts.append(w_counts(0.9))
                    labels.append({"M": int(M), "part": "R", "circuit": "Z", "phi_deg": 0, "copy": cp, "m_clbit": 5}); counts.append(r_counts(0.01))
                    labels.append({"M": int(M), "part": "B", "circuit": "XY4", "phi_deg": 0, "copy": cp, "m_clbit": 5}); counts.append(r_counts(0.04))
            r = analyse(labels, counts)
            want = "SMALL" if L == 0 else "LARGE"
            pm = r["per_M"]
            got = {M: (pm[M]["verdict"], round(pm[M]["L_W_minus_R1"]["deg"], 2), [round(x, 2) for x in pm[M]["L_W_minus_R1"]["ci90"]]) for M in ORDER_M}
            r0 = {M: round(pm[M]["R1_minus_R0"]["deg"], 1) for M in ORDER_M}
            pc = {M: round(pm[M]["pulse_cost"]["P1_minus_Z"], 3) for M in ORDER_M}
            good = all(v[0] == want for v in got.values()) and all(abs(v + 20) < 3 for v in r0.values()) and all(abs(v - 0.03) < 0.01 for v in pc.values())
            ok = ok and good
            print(f"synthetic theta {theta:+d} L {L}: expect {want}; got {got}; R1 - R0 {r0} (stated -20); pulse cost {pc} (stated 0.03); {'PASS' if good else 'FAIL'}")
    print("synthetic overall:", "PASS" if ok else "FAIL")
    return ok
